"""Review-only native crops/boards and lightweight previews; originals untouched."""
from pathlib import Path
from PIL import Image,ImageDraw
import json,hashlib
R=Path(__file__).resolve().parents[1];D=R/'docs/gate3-recovery-world'
regions=[('palace','01 Palace compound'),('academy','02 Academy and hanok courts'),('culture','03 Cultural courtyard'),('transition','04 Heritage garden threshold'),('retail','05 Modern retail street'),('station','06 Railway district'),('namsan','07 Namsan'),('amusement','08 Amusement park'),('market','09 Harbor and waterfront'),('jeju-culture','10 Jeju')]
records=[];cards=[]
for key,title in regions:
 for state in ['before','after']:
  p=D/f'{key}-{state}-native.png';im=Image.open(p);assert im.size==(1280,900)
  # These are explicitly preview derivatives; original native PNGs stay byte-identical.
  preview=im.convert('RGB').resize((640,450),Image.Resampling.NEAREST);out=D/f'{key}-{state}-preview.jpg';preview.save(out,quality=86,optimize=True);assert out.stat().st_size<1000000
  box=(320,260,960,660);crop=im.crop(box);crop.save(D/f'{key}-{state}-crop-1x.png',optimize=True)
  records.append({'source':str(p.relative_to(R)),'sourceSha256':hashlib.sha256(p.read_bytes()).hexdigest(),'preview':out.name,'previewBytes':out.stat().st_size,'previewMethod':'50% nearest resize + JPEG, viewing copy only','nativeCrop':f'{key}-{state}-crop-1x.png','nativeCropRect':list(box),'cropResampling':'NONE'})
 cards.append(f'<article id="{key}"><h2>{title}</h2><div class="pair">'+''.join(f'<figure><a href="{key}-{s}-native.png"><img loading="lazy" src="{key}-{s}-preview.jpg" alt="{title} {s}"></a><figcaption>{s.upper()} · <a href="{key}-{s}-native.png">original1280×900 Phaser PNG</a> · <a href="{key}-{s}-crop-1x.png">unscaled crop</a></figcaption></figure>'for s in ['before','after'])+f'</div><p><a href="../../gate3-review.html?scene=recovery-world&entry={key}&native&worldOnly">Play native framing</a> · <a href="../../gate3-review.html?scene=recovery-world&entry={key}&worldOnly">Play with follow camera</a></p></article>')

# Native benchmark cells, no source resampling. Labels live outside artwork cells.
benchmark=Image.open(R/'docs/gate2/B_NATIVE_1X.png');bw,bh=benchmark.size;benchmark_box=(max(0,bw//2-192),max(0,bh//2-150),max(0,bw//2-192)+384,max(0,bh//2-150)+300)
cells=[('Approved Muneum / original Phaser',benchmark.crop(benchmark_box))]
for key in ['palace','retail','market','station','jeju-culture']:cells.append((key,Image.open(D/f'{key}-after-native.png').crop((448,300,832,600))))
board=Image.new('RGB',(1152,652),'#173133');bd=ImageDraw.Draw(board)
for i,(title,im)in enumerate(cells):
 x=(i%3)*384;y=(i//3)*326;bd.text((x+8,y+7),title,fill='#f4ecd7');board.paste(im.convert('RGB'),(x,y+26))
board.save(D/'muneum-native-benchmark-board.png',optimize=True);board.save(D/'muneum-benchmark-preview.jpg',quality=85,optimize=True)
Image.open(D/'world-overview-phaser.png').convert('RGB').save(D/'world-overview-preview.jpg',quality=87,optimize=True)

# True station field overlay: closed strip plus original logical geometry, not a new connector.
m=json.loads((R/'public/assets/gate3/recovery-world/manifest.json').read_text());shots=json.loads((D/'native-captures.json').read_text());row=next(r for r in shots['rows']if r['name']=='station-after-native');sx,sy=row['audit']['camera']['scroll'];im=Image.open(D/'station-after-native.png').convert('RGBA');over=Image.new('RGBA',im.size);od=ImageDraw.Draw(over)
od.rectangle((2950-sx,2626-sy,2957-sx,2754-sy),fill=(255,45,60,190),outline='white');od.text((2850-sx,2770-sy),'8px STRIP CLOSED',fill='white');im.alpha_composite(over);im.save(D/'station-collision-overlay-native.png',optimize=True)

support=''.join(f'<li><a href="{key}-after-native.png">{label} · original native Phaser PNG</a></li>'for key,label in [('archive','Archive beside Juni'),('platform','Original canopy/platform surroundings'),('maru','Protected Maru'),('ferry','Compact native ferry ticket hall'),('jeju-arrival','Jeju arrival connection'),('jeju-oreum','Original Jeju oreum'),('bookshop-occlusion','Juni visible behind protected bookshop')])
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>G3-D consolidated world recovery review</title><style>body{font:17px/1.5 system-ui;background:#13292d;color:#f2e8d3;max-width:1400px;margin:auto;padding:20px}a{color:#9be4dd}article{padding:16px;background:#20383a;margin:24px 0}.pair{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:14px}figure{margin:0}img,video{max-width:100%;height:auto}img{image-rendering:pixelated}.notice{border-left:4px solid #e9b766;padding:14px;background:#2c3b3d}</style><h1>G3-D · consolidated ten-region recovery candidate</h1><p class="notice"><strong>Final human artistic acceptance is pending.</strong> The shared direction is conditionally approved. Bakery is still required/unplaced. Tower/retail projection, station strip, inherited route failures and physical hardware/device acceptance remain open. New landmark profiles are candidates, not automatically approved art.</p><p><a href="../../gate3-review.html?scene=recovery-world&entry=transition&worldOnly">PLAY REVIEW WORLD</a> · <a href="README.md">QA and remaining decisions</a> · <a href="COVERAGE.md">Actual coverage</a> · <a href="navigation-report.json">Collision/navigation</a> · <a href="DEVICE_REVIEW.md">Physical-device handoff</a></p><h2>Updated world overview</h2><a href="world-overview-phaser.png"><img src="world-overview-preview.jpg" alt="Actual Phaser overview, scaled"></a><p>Actual Phaser overview mode; scaled overview is not native-pixel proof. Native region PNGs below are1280×900, zoom1, DPR1.</p><h2>Actual gameplay</h2><video controls preload="metadata" src="world-traversal-review.mp4"></video><p>Continuous actual WASD/Shift walk,17 destinations including market and ferry approaches; no teleport or collision override. This lightweight video is512×400 at8fps with nearest-neighbor review resize. <a href="world-traversal-native-resolution.mp4">Native-resolution1280×1000 recording copy</a> · <a href="movement-report.json">Actual movement data</a>. Use native PNGs for pixel inspection.</p><h2>Native Muneum craftsmanship comparison</h2><a href="muneum-native-benchmark-board.png"><img src="muneum-benchmark-preview.jpg" alt="Muneum and recovered environments at identical native crop scale"></a><p>Each art cell is an unchanged384×300 native crop. This board is a review derivative; it does not award artistic PASS.</p><h2>Ten-region before/after gallery</h2><p>BEFORE is the preserved three-pilot world context at matching cameras. JPEG previews are under1MB; click through to untouched native Phaser PNGs and original-scale crops.</p>'''+''.join(cards)+'''<h2>Supporting native evidence</h2><ul>'''+support+'''</ul><p><a href="station-collision-overlay-native.png">Closed8px strip overlay</a> · <a href="projection-report.json">Exact landmark projections</a> · <a href="protected-hashes.json">Protected hashes/checkpoints</a> · <a href="asset-provenance.json">Source provenance</a> · <a href="technical-qa.json">Technical QA</a></p><p>No full-world acceptance, main merge or public deployment. Physical Android Chrome and iPhone Safari are NOT TESTED.</p></html>'''
(D/'VISUAL_REVIEW.html').write_text(page);(D/'review-derivatives.json').write_text(json.dumps({'nativeSourceOriginalsModified':False,'records':records,'muneumSource':'docs/gate2/B_NATIVE_1X.png','muneumSourceCrop':list(benchmark_box)},indent=2)+'\n')
print('Prepared',len(regions),'region comparisons; all JPEG previews<1MB')
